join (values ('Traditional Massage', 'Balinesse Massage – Healing (60 min)', 'Incorporates tradtional healing technicques, stokeing and kneding to improve blood circulation', 475200, 'IDR', 0), ('Traditional Massage', 'Tlaga Stress Relief Massage (60 min)', 'Using along stroke massage combine with thumb pressure and lomi lomi a specially focused stress reduction and relaxation', 534600, 'IDR', 1), ('Facial', 'Deep Cleansing Pore Facial (60 min)', 'A deep pore cleansing facial is a facial treatment involving a cleansing procedure that penetrates your skin deeply to...', 457380, 'IDR', 0), ('Other', 'Citrus Milk Bath (45 min)', 'Immerse yourself in a luxurious milk bath, a time-honored spa ritual designed to soften, hydrate, and rejuvenate the skin.', 712800, 'IDR', 0), ('Other', 'Rama & Shinta Royal Harmony (180 min)', 'Exclusive Indulge in a luxurious holiday escape with this signature package, designed to immerse you in deep relaxation.', 2019600, 'IDR', 1), ('Other', 'Tropical Love Escape (120 min)', '(Specially for normal skin) Escape to a paradise of relaxation and romance with this signature treatment.', 950400, 'IDR', 2), ('Other', 'River of Serenity (150 min)', 'Surrender to the tranquil beauty of Bali with the River of Serenity Ritual, designed for you and your partner to experience.', 1544400, 'IDR', 3), ('Other', 'Babymoon Radiance (120 min)', 'The Ultimate Prenatal Escape This luxurious spa treatment is designed specially comfort for mom and baby.', 950400, 'IDR', 4), ('Flower Bath', 'Tlaga Flower Bath (45 min)', 'Escape to our luxurious bathing experience indulgent in a shooting bath infused with calming scents of tropical flowers.', 594000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

