insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Balinese Massage', 'Traditional balinese balance (60 min)', 'Tradition runs deep with these Balinese techniques of kneading, long strokes, and acupressure stimulation. Release muscle tension, improve blood circulation and dissolve stress to re-balance and restore our heart to a state of love and gratitude.', 240000, 'IDR', 0), ('Deep Tissue', 'Deep tissue release (60 min)', 'Based on meridians and acupressure points this deeper therapeutic massage loosens muscle tissues, supports blood and oxygen circulation and releases stress, blockage and toxins. Beneficial for chronic pain, injuries or stubborn knots. You will be kneaded, pressed, stretched, elbowed and stroked into bliss.', 260000, 'IDR', 0), ('Hot Stone', 'Hot stone soothe (90 min)', 'A gentle massage to remind us to slow down and remember we have a body. Warm volcanic stones are placed to warm and relax muscles, then long, slow strokes melt away stress and tension. Perfect to induce sleep, reduce anxiety, for arthritis / aching joints or those who prefer a more gentle, nurturing massage.', 380000, 'IDR', 0), ('Reiki', 'Reiki infused surrender (90 min)', 'Beginning with Reiki to receive healing energy throughout your treatment. Reiki brings your therapist into their highest state and opens their heart to transmit good intentions and positive energy throughout your massage. Techniques used include Balinese, Swedish, deep tissue, lomi-lomi, shiatsu, and reiki. Ending with a head and face massage you are brought back to planet Earth and grounded with ', 400000, 'IDR', 0), ('Reiki', 'Reiki chakra reset (30 min)', 'Chakras are the body’s energy centres that spin and distribute our prana / chi / essential life force. These centres get clogged up over time when we experience stress and negative emotions. We clear each of your 7 individual chakras, releasing blockage, then balance your key chakra centres in relation to their corresponding chakra. We also use coloured crystals over your chakras to amplify your h', 140000, 'IDR', 1), ('Shiatsu', 'Shiatsu unfurl (60 min)', 'A strong massage based on Japanese healing systems release muscle and meridian blockages which cause pain physically, mentally and emotionally. Your therapist works deeply, without oil. Techniques used include acupressure with thumbs, palms, elbows, and the occasional foot! This style of massage can be fully clothed if you prefer.', 280000, 'IDR', 0), ('Foot Massage', 'Foot massage earthing (30 min)', 'Acupressure points on your feet correspond with body systems and can release blockages when stimulated. Sit back and relax whilst your therapist washes your feet then gives a soothing lower leg massage infused with foot reflexology to ground you and connect with mother earth.', 140000, 'IDR', 0), ('Facial', 'Facial – Ibu earth (60 min)', 'Our most popular facial is freshly prepared daily from organic ingredients including natural fruits, oils, seeds, plants, honey and clay to cleanse, exfoliate, tone and moisturise your skin. Included is a gentle neck, arm and leg massage.', 240000, 'IDR', 0), ('Facial', 'Facial – Sanctum (60 min)', 'Sanctum is a range of certified organic, cruelty free, natural facial products from Australia. A perfect fresh lift for your skin. We begin with a cleanse and gentle exfoliant to thoroughly prepare your skin for active ingredients. Whilst your hydrating masque infuses enjoy a neck, arm and leg massage before eye balm and moisturiser are applied.', 300000, 'IDR', 1), ('Manicure', 'Manicure (60 min)', 'After a warm hand soak we cleanse, trim, shape, buff and beautify your nails and cuticles. Polish of your choice is applied and enjoy a hand and arm massage.', 220000, 'IDR', 0), ('Pedicure', 'Pedicure (60 min)', 'Pamper your feet so your toes and heels look and feel healthy. We begin with a foot scrub, then get down to the business of gently removing dry skin and callouses before trimming and shaping your nails. Your treatment includes a relaxing foot massage then we apply colour of your choice.', 220000, 'IDR', 0), ('Cream Bath', 'Infusion – Hair Cream Bath (60 min)', 'We shampoo your hair with our seaweed infused shampoo, then apply a deeply nourishing hair mask treatment that contains candlenut, jojoba and essential oils. Enjoy a deep scalp massage before we wrap your hair in a hot towel and massage your neck, shoulders and arms. Enjoy your soft, shiny, healthy hair.', 240000, 'IDR', 0), ('Other', 'Green Tara compassion (150 min)', 'Your choice of 60 minute massage - Traditional Balinese balance or Foot Massage Earthing plus Reiki chakra reset followed by your choice of Facial – Ibu Earth or Infusion – Hair Cream Bath.', 600000, 'IDR', 0), ('Other', 'Kwan Yin unconditional love (270 min)', 'Your choice of 90 minute massage - Hot stone soothe or Traditional Balinese balance or Deep tissue release plus any body scrub, mask and bath combo followed by your choice of Facial–Ibu Earth or Infusion – Hair Cream Bath plus manicure or pedicure.', 1050000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

