insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Traditional Massage', 'Relaxing Massage (75 min)', 'Warm herbal oil is poured onto your body, followed by a soothing Ayurvedic-inspired massage to calm the nervous system and relieve deep stress, leaving you balanced, relaxed, and fully restored.', 375000, 'IDR', 0), ('Balinese Massage', 'Balinese Massage (60 min)', 'Experience Balinese massage techniques—pressure points, palm pressure, sliding, and kneading for deep relaxation. Release muscle tension, ease pain, and enjoy profound therapeutic benefits.', 325000, 'IDR', 0), ('Other', 'Exfoliation and Bath (45 min)', 'Choose your scrub—lulur, milk, coffee, or green tea—to revitalize your skin. Finish your treatment by relaxing in a beautiful floral bath for a perfect, refreshing feeling.', 350000, 'IDR', 0), ('Other', 'Mandi Susu – Milk Bath (120 min)', 'Experience a timeless beauty ritual inspired by Cleopatra, with a 75-minute relaxing massage, a gentle milk scrub, and a fragrant floral bath for soft, smooth, and glowing skin.', 550000, 'IDR', 1), ('Other', 'Mandi Kopi – Coffee Bath (120 min)', 'Enjoy an invigorating treatment with a 75-minute relaxing massage, a coffee scrub to smooth and tone the skin, and a fragrant floral bath for a refreshed, renewed feeling.', 550000, 'IDR', 2), ('Other', 'Mandi Teh Hijau – Green Tea Bath (120 min)', 'A detoxifying treatment featuring a 75-minute relaxing massage, followed by a green tea scrub to rejuvenate the skin. Finish with a beautiful floral bath for a radiant and refreshed glow.', 550000, 'IDR', 3), ('Other', 'Floral Bath Only (30 min)', 'Immerse yourself in a fresh flower petal bath designed to rejuvenate the senses. Enjoy a quiet moment of relaxation for the body and mind.', 250000, 'IDR', 4), ('Other', 'Hibiscus Hair Shampoo (30 min)', 'This centuries-old Indonesian ritual cleanses and nourishes your scalp with hibiscus extract to stimulate growth, prevent graying, and reveal lustrous hair.', 150000, 'IDR', 5), ('Other', 'A Day at Botanica (375 min)', 'A day of divine pampering starts with a Chakra Dhara, pouring soothing herbal oil over your energy centers, followed by an Ayurvedic massage and full-body scrub. Luxuriate in a flower bath, then enjoy an Ayurvedic facial and nourishing hair treatment. Emerge from this experience feeling revitalized from head to toe.', 2025000, 'IDR', 6), ('Other', 'A Taste of Ayurveda (195 min)', 'Unwind with a 2.5-hour Ayurvedic Chakra Dhara, warm herbal oil is dripped onto the Chakra points, followed by a deep healing massage to promote blood circulation, increase flexibility, and relieve pain. Your treatment concludes with a body exfoliation and soak in a floral bath.', 1195000, 'IDR', 7), ('Other', 'Pure Relaxing (150 min)', 'An indulgent 2,5 hours escape, dedicated to deep relaxation and nurturing. Begin with a tension-melting Balinese massage, experience tranquil bliss with an Ayurvedic Shirodara, followed by a rejuvenating full-body exfoliation. Then unwind in a luxurious flower bath as you embrace complete tranquility.', 1150000, 'IDR', 8), ('Other', 'Romantic Escape for Two (180 min)', 'Indulge in 3 hours of pampering with your loved one, starting with a blissful relaxing massage, followed by luxurious full-body exfoliation, a fragrant flower bath, and a rejuvenating facial—all in the intimate setting of our romantic couples’ room overlooking the jungle.', 2050000, 'IDR', 9), ('Javanese Lulur', 'Mandi Lulur – Floral Bath (120 min)', 'Experience a 17th-century Javanese royal treatment with a 75-minute relaxing massage, a traditional full-body spice scrub, and a fragrant floral bath overlooking the jungle.', 550000, 'IDR', 0), ('Ice Bath', 'Mandi Rempah – Spice Bath (120 min)', 'Experience a 75-minute relaxing massage, a warming spice scrub to improve circulation, and an aromatic herbal bath to soothe, restore, and renew your body.', 550000, 'IDR', 0), ('Body Treatment', 'Coconut Body Treatment (120 min)', 'A deeply hydrating ritual combining a relaxing massage, a gentle coconut body scrub, and a fresh flower bath—ideal for dry and compromised skin.', 550000, 'IDR', 0), ('Foot Massage', 'Foot Spa (60 min)', 'Treat your feet to a relaxing foot spa with a salt and lime soak, nail care, and a 25-minute massage for your feet and lower legs, leaving them refreshed, smooth, and well-groomed.', 275000, 'IDR', 0), ('Facial', 'Gel Mask Facial (60 min)', 'Our therapists gently cleanse and exfoliate your skin before applying a Bio-Aloe Vera mask that hydrates the skin and locks in moisture. The perfect soothing facial for normal to dry skin types, and those who have caught too much Bali sun.', 350000, 'IDR', 0), ('Facial', 'Thermal Clay Facial (60 min)', 'Specially crafted for oily or sensitive skin types, our Balinese clay facial is nature’s facelift! After the therapists gently cleanse and exfoliate your skin, a thermal clay mask is applied to your face and neck to purify and hydrate your skin, restoring its radiance.', 350000, 'IDR', 1), ('Cream Bath', 'Hair Cream Bath (60 min)', 'Rejuvenate dull hair with an avocado cream scalp massage to stimulate circulation and promote growth, followed by a steam bath to lock in moisture for healthy, shiny hair.', 300000, 'IDR', 0), ('Ayurvedic Treatment', 'Ayurvedic Facial (60 min)', 'Our therapists gently cleanse and exfoliate your skin using a classic blend of antioxidant-rich herbs. A soothing Marma point massage calms you, before steam deeply purifies your pores. This facial revives skin texture, restores elasticity to prevent aging and gives you a radiant glow.', 400000, 'IDR', 0), ('Spa Package', 'Bali Byasa Package (240 min)', 'Drift into 4 blissful hours of pure self-care, indulging in the most beloved Bali spa experiences—a dreamy escape your body and soul truly deserve.', 1250000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

