join (values ('Foot Massage', 'Foot Massage (30 min)', 'Through gentle manipulation and aromatic oil, target pressure points and soothe tired muscles in your feet.', 95000, 'IDR', 0), ('Foot Massage', 'Foot Massage (60 min)', 'Through gentle manipulation and aromatic oil, target pressure points and soothe tired muscles in your feet.', 190000, 'IDR', 1), ('Foot Massage', 'Signature Pedicure Footlogix with Polish & Callus (70 min)', 'Give your skin smoother by foot bath & scrubbing, relaxing massage in feet complete with classic pedicure, nail cutting, nail shaping, cuticle care, nail polish applications, callus shaver.', 260000, 'IDR', 2), ('Foot Massage', 'Signature Pedicure Footlogix with Callus (60 min)', 'Foot bath & scrubbing, relaxing massage in feet, complete with classic pedicure, nail cutting, nail shaping, cuticle care, callus shaver.', 250000, 'IDR', 3), ('Foot Massage', 'Relaxing Foot Massage (60 min)', 'A relaxing Foot Massage in Ubud, Bali designed to relieve tired feet and restore overall body balance. Using traditional pressure point techniques, this treatment helps improve blood circulation, reduce muscle tension, and promote deep relaxation after a long day of exploring Ubud.', 190000, 'IDR', 4), ('Foot Massage', 'Relaxing Foot Massage (30 min)', 'A relaxing Foot Massage in Ubud, Bali designed to relieve tired feet and restore overall body balance. Using traditional pressure point techniques, this treatment helps improve blood circulation, reduce muscle tension, and promote deep relaxation after a long day of exploring Ubud.', 95000, 'IDR', 5), ('Reflexology', 'Foot Reflexology (30 min)', 'An ancient healing art, focused applying pressure to specific points on the feet that correspond to organs and system in the body, promoting wellness and relaxations.', 105000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (60 min)', 'An ancient healing art, focused applying pressure to specific points on the feet that correspond to organs and system in the body, promoting wellness and relaxations.', 210000, 'IDR', 1), ('Reflexology', 'Traditional Foot Reflexology (60 min)', 'Foot Reflexology in Ubud, Bali is an ancient healing art, focused applying pressure to specific points on the feet that correspond to organs and system in the body, promoting wellness and relaxations', 210000, 'IDR', 2), ('Reflexology', 'Traditional Foot Reflexology (30 min)', 'Foot Reflexology in Ubud, Bali is an ancient healing art, focused applying pressure to specific points on the feet that correspond to organs and system in the body, promoting wellness and relaxations', 105000, 'IDR', 3), ('Head Massage', 'Head Massage (30 min)', 'A relaxing treatment focusing on the scalp, neck, and shoulders. Helps relieve stress, tension headaches, and promotes better blood circulation.', 95000, 'IDR', 0), ('Traditional Massage', 'Hand Massage (30 min)', 'Targets pressure points in the hands to relieve tension, improve circulation and reduce stress.', 95000, 'IDR', 0), ('Traditional Massage', 'Herbal Massage (90 min)', 'Deeply relaxing massage using warm herbal compresses filled with traditional Balinese herbs to relieve muscle tension, detoxify the body, enhancing relaxation & better sleep.', 450000, 'IDR', 1), ('Traditional Massage', 'Herbal Massage (120 min)', 'Deeply relaxing massage using warm herbal compresses filled with traditional Balinese herbs to relieve muscle tension, detoxify the body, enhancing relaxation & better sleep.', 600000, 'IDR', 2), ('Neck & Shoulder', 'Back, Neck & Shoulder Massage (30 min)', 'Using a fusion of soothing techniques and therapeutic pressure, design to alleviate muscle stiffness, improve circulation,and promote relaxation.', 150000, 'IDR', 0), ('Neck & Shoulder', 'Back, Neck & Shoulder Massage (60 min)', 'Using a fusion of soothing techniques and therapeutic pressure, design to alleviate muscle stiffness, improve circulation,and promote relaxation.', 300000, 'IDR', 1), ('Balinese Massage', 'Balinese Massage (60 min)', 'Trad